	/**
	 * Copies connection settings, including HTTP proxy, SOCKS proxy, bind (network interface) IP address, and TLS options, from ARG1.  This is optional; if not used, default settings apply.  Call this method before Connect.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkMcpRef.html#SetConnectionSettings
	 * @param CkSocket $sock
	 * @return bool
	 */
	function SetConnectionSettings($sock) {
		return CkMcp_SetConnectionSettings($this->_cPtr,$sock);
	}
}
